import numpy as np
import ot
import time

class Solver:
    def __init__(self):
        self.cache = {}

    def solve(self, problem):
        # Can we hash the cost matrix?
        M = problem["cost_matrix"]
        h = hash(M.tobytes())
        if h in self.cache:
            return self.cache[h]

        a = problem["source_weights"]
        b = problem["target_weights"]
        M_cont = np.ascontiguousarray(M, dtype=np.float64)
        G = ot.lp.emd(a, b, M_cont, check_marginals=False)
        self.cache[h] = {"transport_plan": G}
        return self.cache[h]

